using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class OrganizationBoundaryTests
{
 class User(bool manage=true):ICurrentUser{public string Email=>"organizationboundary@example.local";public int? EmployeeId=>1;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>manage&&p==Perm.OrgManage;}
 class Db(DbContextOptions options):AppDbContext(options){public bool Fail;public override async Task<int> SaveChangesAsync(CancellationToken ct=default){var n=await base.SaveChangesAsync(ct);if(Fail)throw new InvalidOperationException("Fictional post-write failure");return n;}}
 static async Task<Db> Open(){var d=new Db(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.EnsureCreatedAsync();d.Add(new Department{Id=1,Name="Fictional existing department",CostCenter="EXISTING"});await d.SaveAsync();return d;}
 static OrgService S(AppDbContext d,bool manage=true){var u=new User(manage);return new(d,new AuditService(d,u,new AppClock(TimeProvider.System)),u);}
 static Task Mutate(AppDbContext d,string path,bool manage=true)=>path switch{"Create"=>S(d,manage).AddDepartmentAsync(" Fictional added department "," قسم تجريبي ",1,null," TEST ",0),"Toggle"=>S(d,manage).ToggleDepartmentAsync(1),_=>S(d,manage).AddJobTitleAsync(" Fictional title "," مسمى تجريبي ",3,10000,20000," Fictional notes ")};
 static async Task Original(AppDbContext d){Assert.Single(await d.Set<Department>().ToListAsync());Assert.True((await d.Set<Department>().FindAsync(1))!.IsActive);Assert.Empty(await d.Set<JobTitle>().ToListAsync());Assert.Empty(await d.Set<AuditLog>().ToListAsync());Assert.False(d.ChangeTracker.HasChanges());}
 [Theory][InlineData("Create")][InlineData("Toggle")][InlineData("Title")]public async Task PostSaveFailureRollsBackAndRetryPersistsOnce(string path){await using var d=await Open();d.Fail=true;await Assert.ThrowsAsync<InvalidOperationException>(()=>Mutate(d,path));d.Fail=false;await Original(d);await Mutate(d,path);Assert.Single(await d.Set<AuditLog>().ToListAsync());if(path=="Create"){var x=await d.Set<Department>().SingleAsync(x=>x.Id!=1);Assert.Equal("Fictional added department",x.Name);Assert.Equal("TEST",x.CostCenter);Assert.Equal(1,x.ParentId);}else if(path=="Toggle")Assert.False((await d.Set<Department>().FindAsync(1))!.IsActive);else Assert.Equal("Fictional title",(await d.Set<JobTitle>().SingleAsync()).Name);}
 [Theory][InlineData("Create")][InlineData("Toggle")][InlineData("Title")]public async Task OuterRollbackRemovesDataAndAudit(string path){await using var d=await Open();await Assert.ThrowsAsync<DomainException>(()=>d.AtomicAsync(async()=>{await Mutate(d,path);throw new DomainException("Fictional outer failure");}));await Original(d);}
 [Theory][InlineData("Create")][InlineData("Toggle")][InlineData("Title")]public async Task DirectServiceCannotBypassManagementGrant(string path){await using var d=await Open();await Assert.ThrowsAsync<DomainException>(()=>Mutate(d,path,false));await Original(d);}
 [Theory][InlineData(999,null,0)][InlineData(null,999,0)][InlineData(null,null,-1)][InlineData(0,null,0)][InlineData(null,0,0)]public async Task InvalidDepartmentReferencesAndNegativeTargetsLeaveNoWrites(int? parent,int? manager,int target){await using var d=await Open();await Assert.ThrowsAsync<DomainException>(()=>S(d).AddDepartmentAsync("Fictional invalid",null,parent,manager,null,target));await Original(d);}
 [Theory][InlineData(0,0,0)][InlineData(13,0,0)][InlineData(3,-1,0)][InlineData(3,100,99)]public async Task TitleValidationMatchesExistingGradeAndRangeForm(int grade,decimal min,decimal max){await using var d=await Open();await Assert.ThrowsAsync<DomainException>(()=>S(d).AddJobTitleAsync("Fictional invalid",null,grade,min,max,null));await Original(d);}
 [Fact]public async Task WorkingManagerRequiredAndOptionalReferencesStillAllowed(){await using var d=await Open();d.Add(new Branch{Id=1,Name="Fictional branch"});d.Add(new JobTitle{Id=1,Name="Fictional role"});d.Add(new Employee{Id=1,Code="FIC-1",FullName="Fictional manager",DepartmentId=1,BranchId=1,JobTitleId=1,Status=EmployeeStatus.Terminated});await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d).AddDepartmentAsync("Fictional refused",null,1,1,null,0));Assert.Single(await d.Set<Department>().ToListAsync());var e=(await d.Set<Employee>().FindAsync(1))!;e.Status=EmployeeStatus.OnLeave;await d.SaveAsync();await S(d).AddDepartmentAsync("Fictional managed",null,1,1,null,0);await S(d).AddDepartmentAsync("Fictional root",null,null,null,null,0);var tree=await S(d).GetAsync();Assert.Equal(2,tree.Tree.Count);Assert.Equal("Fictional manager",tree.Tree.Single(x=>x.Dept.Id==1).Children.Single().ManagerName);}
}
